1	import { App, Alert, Button, Card, Flex, Select, Spin, Switch, Tag, Typography } from 'antd';
2	import { useState } from 'react';
3	import { Link } from 'react-router-dom';
4	
5	import {
6	  type AlertOn,
7	  getNotifications,
8	  putNotifications,
9	  type SuiteNotification,
10	  type SuiteNotificationUpdate,
11	} from '../../api/notifications';
12	import {
13	  linkSuiteChannel,
14	  listChannels,
15	  listSuiteChannels,
16	  type NotificationChannel,
17	  unlinkSuiteChannel,
18	} from '../../api/notificationChannels';
19	import { useAsyncAction } from '../../hooks/useAsyncAction';
20	import { useAsyncData } from '../../hooks/useAsyncData';
21	import { errorMessage } from '../../utils/errors';
22	
23	const ALERT_ON_OPTIONS: { value: AlertOn; label: string }[] = [
24	  { value: 'fail', label: 'On fail / critical' },
25	  { value: 'warn', label: 'On warn and worse' },
26	  { value: 'always', label: 'Always (every run)' },
27	];
