29	/**
30	 * Suite-detail panel for per-suite alerting (W6, fronts `notification_service`; Slack + email per-
31	 * suite added in #633).
32	 */
33	export function NotificationsPanel({
34	  suiteId,
35	  canManage,
36	}: {
37	  suiteId: string;
38	  canManage: boolean;
39	}) {
40	  const { state, reload } = useAsyncData(() => getNotifications(suiteId));
41	  const legacy =
42	    state.status === 'ok' &&
43	    (state.data.has_webhook || state.data.has_slack_webhook || !!state.data.email_recipients);
44	
45	  return (
46	    <Flex vertical gap={16}>
47	      <Card
48	        size="small"
49	        title={
50	          <Flex vertical gap={2}>
51	            <Typography.Text strong>Alerting</Typography.Text>
52	            <Typography.Text type="secondary" style={{ fontSize: 12, fontWeight: 400 }}>
53	              Whether this suite alerts, on what, and to which of the channels an admin configured.
54	            </Typography.Text>
55	          </Flex>
56	        }
57	      >
58	        {state.status === 'loading' ? (
59	          <Spin description="Loading notifications…" />
60	        ) : state.status === 'error' ? (
61	          <Alert
62	            type="error"
63	            showIcon
64	            title="Failed to load notifications"
65	            description={state.error}
66	          />
67	        ) : (
68	          <Flex vertical gap={16}>
69	            <NotificationsForm
70	              // Remount on a config change so the form re-seeds from the loaded values (render-
71	              // phase reset, no setState-in-effect); an unchanged reload keeps the same key.
72	              key={`${state.data.enabled}:${state.data.alert_on}`}
73	              suiteId={suiteId}
74	              canManage={canManage}
75	              initialEnabled={state.data.enabled}
76	              initialAlertOn={state.data.alert_on}
77	              onChanged={reload}
78	            />
79	            <ChannelPicker suiteId={suiteId} canManage={canManage} />
80	          </Flex>
81	        )}
82	      </Card>
83	      {legacy && state.status === 'ok' && (
84	        <LegacyDestinations
85	          suiteId={suiteId}
86	          canManage={canManage}
87	          config={state.data}
88	          onChanged={reload}
89	        />
90	      )}
91	    </Flex>
92	  );
93	}
94	
95	/**
96	 * Reusable-channel linking (#1761, admin-managed destinations from Settings → Notifications).
97	 * Coexists with the legacy per-suite webhook above rather than replacing it — both paths deliver
98	 * independently server-side.
99	 */
100	function ChannelPicker({ suiteId, canManage }: { suiteId: string; canManage: boolean }) {
101	  const linked = useAsyncData(() => listSuiteChannels(suiteId));
102	
103	  return (
104	    <Flex vertical gap={4}>
105	      <Typography.Text type="secondary">Channels</Typography.Text>
106	      {canManage ? (
107	        // `ManagedChannelPicker` mounts synchronously off `canManage` (not gated on
108	        // `linked` resolving), so its OWN listChannels fetch starts in parallel with
109	        // `linked`'s — the pre-#1879 parallelism, preserved for the users who actually
110	        // exercise this picker.
111	        <ManagedChannelPicker suiteId={suiteId} linked={linked} />
112	      ) : (
113	        <>
114	          {linked.state.status === 'loading' && <Spin description="Loading channels…" />}
115	          {linked.state.status === 'error' && (
116	            <Alert
117	              type="error"
118	              showIcon
119	              title="Failed to load linked channels"
120	              description={linked.state.error}
121	            />
122	          )}
123	          {linked.state.status === 'ok' &&
124	            (linked.state.data.length === 0 ? (
125	              <Typography.Text type="secondary">No channels linked.</Typography.Text>
126	            ) : (
127	              <Flex gap={4} wrap>
128	                {linked.state.data.map((c) => (
129	                  <Tag key={c.id}>{c.name}</Tag>
130	                ))}
131	              </Flex>
132	            ))}
133	        </>
134	      )}
135	      <Typography.Text type="secondary" style={{ fontSize: 12 }}>
136	        Channels are created once by a workspace admin under{' '}
137	        <Link to="/admin/settings">Settings → Notification channels</Link> and linked here. A suite
138	        with none linked still alerts through the workspace defaults.
139	      </Typography.Text>
140	    </Flex>
141	  );
142	}
143	
144	/** The editable multi-select — mounted only for a `canManage` caller (#1879), so its
145	 *  `listChannels` fetch (the full workspace list, needed for the option set) never
146	 *  runs for a viewer. Takes `linked`'s async state as a prop rather than re-fetching,
147	 *  so the two GETs still fire in parallel (mounting this component on `canManage`
148	 *  alone, not on `linked` having already resolved, is what keeps them concurrent —
149	 *  see the #1879-review follow-up that caught the sequential-fetch regression in an
150	 *  earlier version of this fix). */
151	function ManagedChannelPicker({
152	  suiteId,
153	  linked,
154	}: {
155	  suiteId: string;
156	  linked: ReturnType<typeof useAsyncData<NotificationChannel[]>>;
157	}) {
158	  const all = useAsyncData(listChannels);
159	
160	  if (all.state.status === 'loading' || linked.state.status === 'loading') {
161	    return <Spin description="Loading channels…" />;
162	  }
163	  if (all.state.status === 'error') {
164	    return (
165	      <Alert type="error" showIcon title="Failed to load channels" description={all.state.error} />
166	    );
167	  }
168	  if (linked.state.status === 'error') {
169	    return (
170	      <Alert
171	        type="error"
172	        showIcon
173	        title="Failed to load linked channels"
174	        description={linked.state.error}
175	      />
176	    );
177	  }
178	  return (
179	    <ChannelPickerBody
180	      // Remount when the linked set actually changes underneath us (render-
181	      // phase reset, no setState-in-effect) — a same-set reload keeps the key.
182	      key={linked.state.data
183	        .map((c) => c.id)
184	        .sort()
185	        .join(',')}
186	      suiteId={suiteId}
187	      allChannels={all.state.data}
188	      initialLinked={linked.state.data}
189	      onResync={linked.reload}
190	    />
191	  );
192	}
193	
194	function ChannelPickerBody({
195	  suiteId,
196	  allChannels,
197	  initialLinked,
198	  onResync,
199	}: {
200	  suiteId: string;
201	  allChannels: NotificationChannel[];
202	  initialLinked: NotificationChannel[];
203	  onResync: () => void;
204	}) {
205	  const { message } = App.useApp();
206	  const [selected, setSelected] = useState<string[]>(initialLinked.map((c) => c.id));
207	  const [saving, setSaving] = useState(false);
208	
209	  const onChange = async (nextIds: string[]) => {
210	    const added = nextIds.filter((id) => !selected.includes(id));
211	    const removed = selected.filter((id) => !nextIds.includes(id));
212	    setSelected(nextIds); // optimistic — diffed against the prior selection, not blown away/recreated
213	    setSaving(true);
214	    try {
215	      await Promise.all([
216	        ...added.map((id) => linkSuiteChannel(suiteId, id)),
217	        ...removed.map((id) => unlinkSuiteChannel(suiteId, id)),
218	      ]);
219	    } catch (err) {
220	      message.error(`Failed to update linked channels: ${errorMessage(err)}`);
221	      onResync(); // resync the checked set to whatever actually landed server-side
222	    } finally {
223	      setSaving(false);
224	    }
225	  };
226	
227	  return (
228	    <Select
229	      mode="multiple"
230	      value={selected}
231	      onChange={(v) => void onChange(v)}
232	      disabled={saving}
233	      loading={saving}
234	      style={{ width: '100%' }}
235	      placeholder="No channels linked"
236	      aria-label="Linked channels"
237	      options={allChannels.map((c) => ({ value: c.id, label: `${c.name} (${c.type})` }))}
238	    />
239	  );
240	}
241	
242	/** Shown only while a suite still carries a per-suite webhook or recipient list from
243	 *  before channels existed. Nothing here can be SET — an editor can only clear it and
244	 *  link a channel instead; setting stays an Admin escape hatch on the API. */
245	function LegacyDestinations({
246	  suiteId,
247	  canManage,
248	  config,
249	  onChanged,
250	}: {
251	  suiteId: string;
252	  canManage: boolean;
253	  config: SuiteNotification;
254	  onChanged: () => void;
255	}) {
256	  const { run, loading } = useAsyncAction('Could not clear the destination');
257	  // Clearing sends the loaded (server-known) enabled/alert_on so it never persists an
258	  // unsaved edit from the form above (#639 review).
259	  const clear = (extra: Partial<SuiteNotificationUpdate>) => () =>
260	    void run(async () => {
261	      await putNotifications(suiteId, {
262	        enabled: config.enabled,
263	        alert_on: config.alert_on,
264	        ...extra,
265	      });
266	      onChanged();
267	    });
268	  const rows: { label: string; set: boolean; extra: Partial<SuiteNotificationUpdate> }[] = [
269	    { label: 'Teams webhook', set: config.has_webhook, extra: { webhook: '' } },
270	    { label: 'Slack webhook', set: config.has_slack_webhook, extra: { slack_webhook: '' } },
271	    {
272	      label: `Email recipients${config.email_recipients ? ` (${config.email_recipients})` : ''}`,
273	      set: !!config.email_recipients,
274	      extra: { email_recipients: '' },
275	    },
276	  ];
277	  return (
278	    <Card
279	      size="small"
280	      title={
281	        <Flex vertical gap={2}>
282	          <Typography.Text strong>Legacy inline destinations</Typography.Text>
283	          <Typography.Text type="secondary" style={{ fontSize: 12, fontWeight: 400 }}>
284	            Set on this suite before channels existed. Move it to a channel above, then clear it.
285	          </Typography.Text>
286	        </Flex>
287	      }
288	    >
289	      <Flex vertical gap={8}>
290	        {rows
291	          .filter((r) => r.set)
292	          .map((r) => (
293	            <Flex key={r.label} align="center" gap={8} wrap>
294	              <Tag color="warning">{r.label}</Tag>
295	              {canManage && (
296	                <Button size="small" loading={loading} onClick={clear(r.extra)}>
297	                  Clear
298	                </Button>
299	              )}
300	            </Flex>
301	          ))}
302	      </Flex>
303	    </Card>
304	  );
305	}
306	
307	function NotificationsForm({
308	  suiteId,
309	  canManage,
310	  initialEnabled,
311	  initialAlertOn,
312	  onChanged,
313	}: {
314	  suiteId: string;
315	  canManage: boolean;
316	  initialEnabled: boolean;
317	  initialAlertOn: AlertOn;
318	  onChanged: () => void;
319	}) {
320	  const { message } = App.useApp();
321	  const [enabled, setEnabled] = useState(initialEnabled);
322	  const [alertOn, setAlertOn] = useState<AlertOn>(initialAlertOn);
323	  const { run, loading: saving } = useAsyncAction('Save failed');
324	
325	  const onSave = () =>
326	    void run(async () => {
327	      await putNotifications(suiteId, { enabled, alert_on: alertOn });
328	      message.success('Notifications saved');
329	      onChanged();
330	    });
331	
332	  return (
333	    <Flex vertical gap={16}>
334	      <Flex align="center" gap={12}>
335	        <Switch
336	          checked={enabled}
337	          disabled={!canManage}
338	          onChange={setEnabled}
339	          aria-label="Enable notifications"
340	        />
341	        <Typography.Text>Send alerts for this suite</Typography.Text>
342	      </Flex>
343	
344	      <Flex vertical gap={4}>
345	        <Typography.Text type="secondary">Alert threshold</Typography.Text>
346	        <Select<AlertOn>
347	          value={alertOn}
348	          onChange={setAlertOn}
349	          disabled={!canManage || !enabled}
350	          options={ALERT_ON_OPTIONS}
351	          style={{ maxWidth: 280 }}
352	          aria-label="Alert threshold"
353	        />
354	      </Flex>
355	
356	      {canManage && (
357	        <Button
358	          type="primary"
359	          loading={saving}
360	          onClick={onSave}
361	          style={{ alignSelf: 'flex-start' }}
362	        >
363	          Save
364	        </Button>
365	      )}
366	    </Flex>
367	  );
368	}
