16	import {
17	  type AdminUser,
18	  type OffboardPreview,
19	  type OffboardReceipt,
20	  offboardUser,
21	  previewOffboarding,
22	} from '../../api/admin';
23	import { type UserSummary } from '../../api/shares';
24	import { UserSearchSelect } from '../../components/shared/UserSearchSelect';
25	import { useAsyncAction } from '../../hooks/useAsyncAction';
26	import { errorMessage } from '../../utils/errors';
27	
28	/** Offboard a departing user in one pass: hand over their suites, revoke their
29	 *  PATs and browser sessions, withdraw their membership. Mount it keyed on the
30	 *  user — the preview and the picker are per-user and must not survive a
31	 *  different one being opened. */
32	export function OffboardModal({
33	  user,
34	  onClose,
35	  onOffboarded,
36	}: {
37	  /** `null` closes the modal. */
38	  user: AdminUser | null;
39	  onClose: () => void;
40	  onOffboarded: () => void;
41	}) {
42	  const { message } = App.useApp();
43	  const [preview, setPreview] = useState<OffboardPreview>();
44	  const [previewError, setPreviewError] = useState<string>();
45	  const [receipt, setReceipt] = useState<OffboardReceipt>();
46	  const [picked, setPicked] = useState<UserSummary>();
47	  const [typed, setTyped] = useState('');
48	  const { run, loading: submitting } = useAsyncAction('Offboarding failed');
49	
50	  const userId = user?.id;
51	
52	  // Fetch only. Per-user state is reset by REMOUNTING (the page keys the modal
53	  // per user), not by clearing it here — clearing state inside an effect
54	  // body cascades renders, and a stale receipt surviving into the next user's
55	  // modal is exactly the bug the key rules out.
56	  useEffect(() => {
57	    if (!userId) return;
58	    const controller = new AbortController();
59	    previewOffboarding(userId, controller.signal)
60	      .then(setPreview)
61	      .catch((err: unknown) => {
62	        if (!controller.signal.aborted) setPreviewError(errorMessage(err));
63	      });
64	    return () => controller.abort();
65	  }, [userId]);
66	
67	  const needsOwner = (preview?.owned_suites.length ?? 0) > 0;
68	  const confirmed =
69	    preview !== undefined && typed.trim().toLowerCase() === preview.email.toLowerCase();
70	  const blocked = preview?.is_last_admin === true;
71	  const ready = confirmed && !blocked && (!needsOwner || picked !== undefined);
72	
73	  const onOk = () =>
74	    void run(async () => {
75	      if (!userId || !preview || !ready) return;
76	      const result = await offboardUser(userId, {
77	        new_owner_user_id: picked?.id ?? null,
78	        keep_previous_owner_access: false,
79	        // What the admin typed, not the preview's value: the server-side check is only a
80	        // guard if it sees a human's input.
81	        confirm_email: typed.trim(),
82	      });
83	      setReceipt(result);
84	      message.success(`${preview.email} has been offboarded`);
85	      onOffboarded();
86	    });
87	  const done = receipt !== undefined;
88	
89	  return (
90	    <Modal
91	      title={user ? `Offboard ${user.email}` : 'Offboard user'}
92	      open={user !== null}
93	      onCancel={onClose}
94	      footer={
95	        done ? (
96	          <Button type="primary" onClick={onClose}>
97	            Done
98	          </Button>
99	        ) : undefined
100	      }
101	      onOk={onOk}
102	      okText="Offboard"
103	      okButtonProps={{ danger: true, disabled: !ready, loading: submitting }}
104	      destroyOnHidden
105	      width={620}
106	    >
107	      {receipt ? (
108	        <Receipt receipt={receipt} />
109	      ) : previewError ? (
110	        <Alert
111	          type="error"
112	          showIcon
113	          title="Could not load the preview"
114	          description={previewError}
115	        />
116	      ) : !preview ? (
117	        <Spin size="large" />
118	      ) : (
119	        <Flex vertical gap={12}>
120	          {blocked && (
121	            <Alert
122	              type="error"
123	              showIcon
124	              title="This is the last admin in the workspace"
125	              description="Promote another admin first — offboarding this account would leave nobody able to administer the workspace."
126	            />
127	          )}
128	          {preview.is_self && (
129	            <Alert
130	              type="warning"
131	              showIcon
132	              title="This is you"
133	              description="Offboarding your own account signs you out and revokes your own tokens."
134	            />
135	          )}
136	          <Descriptions size="small" column={1} bordered>
137	            <Descriptions.Item label="Suites they own">
138	              {preview.owned_suites.length}
139	            </Descriptions.Item>
140	            <Descriptions.Item label="Personal access tokens">
141	              {preview.open_api_key_count} live
142	            </Descriptions.Item>
143	            <Descriptions.Item label="Browser sessions">
144	              {preview.live_session_count} live
145	            </Descriptions.Item>
146	            <Descriptions.Item label="Workspace membership">
147	              <MembershipNote preview={preview} />
148	            </Descriptions.Item>
149	          </Descriptions>
150	          {needsOwner && (
151	            <>
152	              <List
153	                size="small"
154	                bordered
155	                header={<Typography.Text strong>These suites need a new owner</Typography.Text>}
156	                dataSource={preview.owned_suites}
157	                renderItem={(suite) => (
158	                  <List.Item>
159	                    <Typography.Text>{suite.name}</Typography.Text>
160	                    <Typography.Text type="secondary">
161	                      {suite.check_count} check(s) · {suite.run_count} run(s)
162	                    </Typography.Text>
163	                  </List.Item>
164	                )}
165	              />
166	              <UserSearchSelect
167	                value={picked}
168	                onChange={setPicked}
169	                // A viewer cannot own a suite and the leaver cannot inherit their own —
170	                // the backend rejects both, so neither is offered.
171	                exclude={(u) => u.role === 'viewer' || u.id === userId}
172	                ariaLabel="New owner"
173	              />
174	              <Typography.Text type="secondary">
175	                The departing user keeps no access to the suites they hand over. Workspace viewers
176	                can’t own a suite, so they aren’t listed.
177	              </Typography.Text>
178	            </>
179	          )}
180	          <Typography.Text>
181	            Type <Typography.Text code>{preview.email}</Typography.Text> to confirm.
182	          </Typography.Text>
183	          <Input
184	            value={typed}
185	            onChange={(e) => setTyped(e.target.value)}
186	            placeholder={preview.email}
187	            aria-label="Confirm email address"
188	            disabled={blocked}
189	          />
190	          <Typography.Text type="secondary">
191	            Their authored history stays: the runs, results and checks they created keep their name
192	            on them, and the account itself is not deleted.
193	          </Typography.Text>
194	        </Flex>
195	      )}
196	    </Modal>
197	  );
198	}
199	
200	function MembershipNote({ preview }: { preview: OffboardPreview }) {
201	  if (preview.membership_state === 'member') {
202	    return (
203	      <Flex vertical gap={4}>
204	        <Tag color="blue">will be withdrawn</Tag>
205	        {preview.still_admitted_by.length > 0 && (
206	          <Typography.Text type="warning" style={{ fontSize: 12 }}>
207	            {preview.membership_note}
208	          </Typography.Text>
209	        )}
210	      </Flex>
211	    );
212	  }
213	  return (
214	    <Flex vertical gap={4}>
215	      <Tag color="orange">
216	        {preview.membership_state === 'env_listed' ? 'env-listed' : 'not a member'}
217	      </Tag>
218	      <Typography.Text type="secondary" style={{ fontSize: 12 }}>
219	        {preview.membership_note}
220	      </Typography.Text>
221	    </Flex>
222	  );
223	}
224	
225	function Receipt({ receipt }: { receipt: OffboardReceipt }) {
226	  return (
227	    <Flex vertical gap={12}>
228	      <Alert type="success" showIcon title={`${receipt.email} has been offboarded`} />
229	      <Descriptions size="small" column={1} bordered>
230	        <Descriptions.Item label="Suites transferred">
231	          {receipt.transferred_suite_ids.length}
232	        </Descriptions.Item>
233	        <Descriptions.Item label="Tokens revoked">{receipt.api_keys_revoked}</Descriptions.Item>
234	        <Descriptions.Item label="Sessions revoked">{receipt.sessions_revoked}</Descriptions.Item>
235	        <Descriptions.Item label="Membership withdrawn">
236	          {receipt.membership_removed ? 'yes' : 'no'}
237	        </Descriptions.Item>
238	        <Descriptions.Item label="Role">
239	          {receipt.role_demoted_from
240	            ? `${receipt.role_demoted_from} → viewer`
241	            : 'viewer (unchanged)'}
242	        </Descriptions.Item>
243	      </Descriptions>
244	      {receipt.still_admitted_by.length > 0 && (
245	        <Alert
246	          type="warning"
247	          showIcon
248	          title="Still admitted by the environment"
249	          description={`${receipt.still_admitted_by.join(' and ')} still admits ${receipt.email} on its own. Remove it there and restart — until then they can sign in.`}
250	        />
251	      )}
252	      {receipt.skipped.length > 0 && (
253	        <List
254	          size="small"
255	          bordered
256	          header={<Typography.Text strong>Not done, and why</Typography.Text>}
257	          dataSource={receipt.skipped}
258	          renderItem={(step) => (
259	            <List.Item>
260	              <Typography.Text type="secondary">
261	                <Typography.Text code>{step.step}</Typography.Text> — {step.reason}
262	              </Typography.Text>
263	            </List.Item>
264	          )}
265	        />
266	      )}
267	    </Flex>
268	  );
269	}
