34	import { useConfirmDelete } from '../../hooks/useConfirmDelete';
35	import { AsyncBody } from '../AsyncBody';
36	import { errorMessage } from '../../utils/errors';
37	
38	/**
39	 * Admin → Settings: reusable notification channels (#1514/#1662/#1663/#1761) — a destination
40	 * defined once and linked from many suites (the per-suite picker lives on
41	 * `NotificationsPanel`). Channel CRUD is Admin-only server-side; this card is only ever mounted
42	 * behind the Settings page's own `is_workspace_admin` gate.
43	 */
44	export function NotificationChannelsPanel() {
45	  const { state, reload } = useAsyncData(listChannels);
46	  const [modal, setModal] = useState<{ channel?: NotificationChannel } | null>(null);
47	
48	  return (
49	    <Card
50	      size="small"
51	      title={
52	        <Flex vertical gap={2}>
53	          <Typography.Text strong>Notification channels</Typography.Text>
54	          <Typography.Text type="secondary" style={{ fontSize: 12, fontWeight: 400 }}>
55	            Reusable Teams/Slack/email/webhook destinations, linked to any number of suites.
56	          </Typography.Text>
57	        </Flex>
58	      }
59	    >
60	      <AsyncBody
61	        state={state}
62	        loadingText="Loading channels…"
63	        errorTitle="Failed to load notification channels"
64	      >
65	        {(channels) => (
66	          <Flex vertical gap={12}>
67	            <Flex justify="flex-end">
68	              <Button type="primary" icon={<PlusOutlined />} onClick={() => setModal({})}>
69	                New channel
70	              </Button>
71	            </Flex>
72	            {channels.length === 0 ? (
73	              <Empty image={Empty.PRESENTED_IMAGE_SIMPLE} description="No channels yet." />
74	            ) : (
75	              <ChannelTable
76	                channels={channels}
77	                onEdit={(channel) => setModal({ channel })}
78	                onChanged={reload}
79	              />
80	            )}
81	            {modal !== null && (
82	              <ChannelFormModal
83	                // Mount fresh per open so the form's initial state (seeded from
84	                // `channel` in each `useState`) actually reflects which channel —
85	                // or none, for create — was clicked; an always-mounted modal
86	                // would seed once from the first render and never re-seed.
87	                key={modal.channel?.id ?? 'new'}
88	                open
89	                channel={modal.channel}
90	                onClose={() => setModal(null)}
91	                onSaved={reload}
92	              />
93	            )}
94	          </Flex>
95	        )}
96	      </AsyncBody>
97	    </Card>
98	  );
99	}
100	
101	function destinationSummary(c: NotificationChannel): string {
102	  switch (c.type) {
103	    case 'teams':
104	    case 'slack':
105	      return c.has_webhook ? 'webhook set' : 'no webhook';
106	    case 'email':
107	      return c.email_recipients || 'no recipients';
108	    case 'webhook':
