208	/** Parses the payload-template textarea; `undefined` for blank, throws for bad JSON. */
209	function parseTemplate(text: string): Record<string, unknown> | undefined {
210	  const trimmed = text.trim();
211	  if (!trimmed) return undefined;
212	  const parsed: unknown = JSON.parse(trimmed);
213	  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
214	    throw new Error('must be a JSON object');
215	  }
216	  return parsed as Record<string, unknown>;
217	}
218	
219	function ChannelFormModal({
220	  open,
221	  channel,
222	  onClose,
223	  onSaved,
224	}: {
225	  open: boolean;
226	  /** `undefined` = create. */
227	  channel?: NotificationChannel;
228	  onClose: () => void;
229	  onSaved: () => void;
230	}) {
231	  const { message } = App.useApp();
232	  const isEdit = channel !== undefined;
233	
234	  const [name, setName] = useState(channel?.name ?? '');
235	  const [type, setType] = useState<ChannelType>(channel?.type ?? 'teams');
236	  const [webhook, setWebhook] = useState('');
237	  const [clearWebhook, setClearWebhook] = useState(false);
238	  const [emailRecipients, setEmailRecipients] = useState(channel?.email_recipients ?? '');
239	  const [webhookUrl, setWebhookUrl] = useState(channel?.webhook_url ?? '');
240	  const [payloadTemplate, setPayloadTemplate] = useState(
241	    channel?.payload_template ? JSON.stringify(channel.payload_template, null, 2) : '',
242	  );
243	  const [clearPayloadTemplate, setClearPayloadTemplate] = useState(false);
244	  const [authHeaderName, setAuthHeaderName] = useState(channel?.auth_header_name ?? '');
245	  const [authHeaderValue, setAuthHeaderValue] = useState('');
246	  const [clearAuthHeaderValue, setClearAuthHeaderValue] = useState(false);
247	  const [regenerateHmac, setRegenerateHmac] = useState(false);
248	  const [templateError, setTemplateError] = useState<string>();
249	  const [saving, setSaving] = useState(false);
250	  // The freshly minted plaintext HMAC key, shown exactly once — never persisted
251	  // beyond this modal's local state, cleared on close.
252	  const [revealedSecret, setRevealedSecret] = useState<string | null>(null);
253	
254	  // No reset-on-close: the modal unmounts (a fresh `key` per open in the parent) the instant
