256	  // — this used to be dead code).
257	
258	  const onSubmit = async () => {
259	    let template: Record<string, unknown> | undefined;
260	    try {
261	      template = parseTemplate(payloadTemplate);
262	      setTemplateError(undefined);
263	    } catch {
264	      setTemplateError('Payload template must be valid JSON (an object)');
265	      return;
266	    }
267	    setSaving(true);
268	    try {
269	      let saved: NotificationChannel;
270	      if (isEdit) {
271	        const payload: ChannelUpdatePayload = { name: name.trim() || undefined };
272	        if (clearWebhook) payload.webhook = '';
273	        else if (webhook.trim()) payload.webhook = webhook.trim();
274	        if (emailRecipients !== (channel.email_recipients ?? '')) {
275	          payload.email_recipients = emailRecipients.trim();
276	        }
277	        if (webhookUrl !== (channel.webhook_url ?? '')) payload.webhook_url = webhookUrl.trim();
278	        if (clearPayloadTemplate) payload.clear_payload_template = true;
279	        else if (template !== undefined) payload.payload_template = template;
280	        if (authHeaderName !== (channel.auth_header_name ?? '')) {
281	          payload.auth_header_name = authHeaderName.trim();
282	        }
283	        if (clearAuthHeaderValue) payload.auth_header_value = '';
284	        else if (authHeaderValue.trim()) payload.auth_header_value = authHeaderValue.trim();
285	        if (regenerateHmac) payload.regenerate_hmac_secret = true;
286	        saved = await updateChannel(channel.id, payload);
287	      } else {
288	        const payload: ChannelCreatePayload = { name: name.trim(), type };
289	        if (webhook.trim()) payload.webhook = webhook.trim();
290	        if (emailRecipients.trim()) payload.email_recipients = emailRecipients.trim();
