292	        if (template !== undefined) payload.payload_template = template;
293	        if (authHeaderName.trim()) payload.auth_header_name = authHeaderName.trim();
294	        if (authHeaderValue.trim()) payload.auth_header_value = authHeaderValue.trim();
295	        saved = await createChannel(payload);
296	      }
297	      message.success(isEdit ? 'Channel saved' : 'Channel created');
298	      onSaved();
299	      if (saved.hmac_secret) {
300	        // Two states in one modal: form → the one-time secret reveal (mirrors
