326	      destroyOnHidden
327	      mask={{ closable: !revealedSecret }}
328	      footer={
329	        revealedSecret ? (
330	          <Button type="primary" onClick={onClose}>
331	            Done
332	          </Button>
333	        ) : (
334	          [
335	            <Button key="cancel" onClick={onClose}>
336	              Cancel
337	            </Button>,
338	            <Button
339	              key="save"
