341	              loading={saving}
342	              disabled={!name.trim()}
343	              onClick={onSubmit}
344	            >
345	              {isEdit ? 'Save' : 'Create'}
346	            </Button>,
347	          ]
348	        )
349	      }
350	    >
351	      {revealedSecret ? (
352	        <Flex vertical gap={12}>
353	          <Alert
354	            type="warning"
355	            showIcon
356	            title="This HMAC signing key is shown only once"
357	            description="Copy it now and store it securely — DataQ signs outbound webhook payloads with it and cannot show it again."
358	          />
359	          <Typography.Paragraph
360	            code
361	            copyable={{ text: revealedSecret }}
362	            style={{ margin: 0, wordBreak: 'break-all' }}
363	          >
364	            {revealedSecret}
365	          </Typography.Paragraph>
366	        </Flex>
367	      ) : (
368	        <Form layout="vertical">
369	          <Form.Item label="Name" required>
370	            <Input
371	              value={name}
372	              onChange={(e) => setName(e.target.value)}
373	              maxLength={128}
374	              aria-label="Channel name"
375	            />
376	          </Form.Item>
377	          <Form.Item label="Type">
378	            {isEdit ? (
379	              <Tag>{CHANNEL_TYPE_LABELS[type]}</Tag>
380	            ) : (
381	              <Select<ChannelType>
382	                value={type}
383	                onChange={(next) => {
384	                  // A create-only field belongs to exactly one type — switching types with a
385	                  // filled-in field from the PREVIOUS type left in place sends a payload the
386	                  // backend's `_validate_destination` rejects (422, #1878 review): both `webhook`
387	                  // and `webhook_url` set at once looks like nothing the user actually did.
388	                  setType(next);
389	                  setWebhook('');
390	                  setWebhookUrl('');
391	                  setEmailRecipients('');
392	                  setAuthHeaderName('');
393	                  setAuthHeaderValue('');
394	                  setPayloadTemplate('');
395	                }}
396	                aria-label="Channel type"
397	                options={CHANNEL_TYPES.map((t) => ({ value: t, label: CHANNEL_TYPE_LABELS[t] }))}
398	              />
399	            )}
400	          </Form.Item>
401	
402	          {(type === 'teams' || type === 'slack') && (
403	            <Form.Item label={`${CHANNEL_TYPE_LABELS[type]} webhook URL`}>
404	              <Flex vertical gap={4}>
405	                <Input.Password
406	                  value={webhook}
407	                  disabled={clearWebhook}
408	                  onChange={(e) => setWebhook(e.target.value)}
409	                  placeholder={
410	                    isEdit && channel.has_webhook
411	                      ? 'Stored — leave blank to keep, or type a new URL to replace it'
412	                      : 'https://…'
413	                  }
414	                  aria-label="Webhook URL"
415	                />
416	                {isEdit && channel.has_webhook && (
417	                  <Checkbox
418	                    checked={clearWebhook}
419	                    onChange={(e) => setClearWebhook(e.target.checked)}
420	                  >
421	                    Clear the stored webhook
422	                  </Checkbox>
423	                )}
424	              </Flex>
425	            </Form.Item>
426	          )}
427	
428	          {type === 'email' && (
429	            <Form.Item label="Recipients">
430	              <Input
431	                value={emailRecipients}
432	                onChange={(e) => setEmailRecipients(e.target.value)}
433	                placeholder="a@example.com, b@example.com"
434	                aria-label="Email recipients"
435	              />
436	            </Form.Item>
437	          )}
438	
439	          {type === 'webhook' && (
440	            <>
441	              <Form.Item label="Webhook URL">
442	                <Input
443	                  value={webhookUrl}
444	                  onChange={(e) => setWebhookUrl(e.target.value)}
445	                  placeholder="https://…"
446	                  aria-label="Webhook destination URL"
447	                />
448	              </Form.Item>
449	              {isEdit && (
450	                <Form.Item>
451	                  <Checkbox
452	                    checked={regenerateHmac}
453	                    onChange={(e) => setRegenerateHmac(e.target.checked)}
454	                  >
455	                    Regenerate HMAC signing key (invalidates the current one)
456	                  </Checkbox>
457	                </Form.Item>
458	              )}
459	              <Form.Item
460	                label="Payload template (optional)"
461	                validateStatus={templateError ? 'error' : undefined}
462	                help={templateError}
463	              >
464	                <Flex vertical gap={4}>
465	                  <Input.TextArea
466	                    value={payloadTemplate}
467	                    disabled={clearPayloadTemplate}
468	                    onChange={(e) => setPayloadTemplate(e.target.value)}
469	                    rows={4}
470	                    placeholder='{"summary": "{{suite.name}} {{run.status}}"}'
471	                    aria-label="Payload template"
472	                  />
473	                  {isEdit && channel.has_payload_template && (
474	                    <Checkbox
475	                      checked={clearPayloadTemplate}
476	                      onChange={(e) => setClearPayloadTemplate(e.target.checked)}
477	                    >
