() => {
  const results = [];
  document.querySelectorAll('.ant-table-wrapper').forEach((w, i) => {
    const content = w.querySelector('.ant-table-content');
    const table = content ? content.querySelector('table') : null;
    if (!content || !table) return;
    results.push({
      i,
      wrapperClientWidth: content.clientWidth,
      tableScrollWidth: table.scrollWidth,
      overflowX: getComputedStyle(content).overflowX,
    });
  });
  return results;
}

